-- Rodos Linea: точні кольори, види полотна й фото з офіційних карток Rodos.
-- Скрипт не змінює інші колекції або бренди. Кожна модель очищається тільки перед повторним наповненням її конфігуратора.
do $$ begin if (select count(*) from public.products where slug in ('rodos-official-9fntu5','rodos-official-9fntu6','rodos-official-9fntu7','rodos-official-9fntu0','rodos-official-9fntu1','rodos-official-9fntu2','rodos-official-9fntu3','rodos-official-9fnttw')) <> 8 then raise exception 'Не знайдено всі моделі Rodos Linea для пакета — каталог не змінено'; end if; end $$;
begin;
delete from public.product_options where product_slug = 'rodos-official-9fntu5';
delete from public.product_variants where product_slug = 'rodos-official-9fntu5';
delete from public.product_media where product_slug = 'rodos-official-9fntu5' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-9fntu6';
delete from public.product_variants where product_slug = 'rodos-official-9fntu6';
delete from public.product_media where product_slug = 'rodos-official-9fntu6' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-9fntu7';
delete from public.product_variants where product_slug = 'rodos-official-9fntu7';
delete from public.product_media where product_slug = 'rodos-official-9fntu7' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-9fntu0';
delete from public.product_variants where product_slug = 'rodos-official-9fntu0';
delete from public.product_media where product_slug = 'rodos-official-9fntu0' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-9fntu1';
delete from public.product_variants where product_slug = 'rodos-official-9fntu1';
delete from public.product_media where product_slug = 'rodos-official-9fntu1' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-9fntu2';
delete from public.product_variants where product_slug = 'rodos-official-9fntu2';
delete from public.product_media where product_slug = 'rodos-official-9fntu2' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-9fntu3';
delete from public.product_variants where product_slug = 'rodos-official-9fntu3';
delete from public.product_media where product_slug = 'rodos-official-9fntu3' and label like 'config:%';
delete from public.product_options where product_slug = 'rodos-official-9fnttw';
delete from public.product_variants where product_slug = 'rodos-official-9fnttw';
delete from public.product_media where product_slug = 'rodos-official-9fnttw' and label like 'config:%';
commit;
select product_slug, count(*) filter (where option_group = 'color') as кольорів, count(*) filter (where option_group = 'configuration') as видів_полотна from public.product_options where product_slug in ('rodos-official-9fntu5','rodos-official-9fntu6','rodos-official-9fntu7','rodos-official-9fntu0','rodos-official-9fntu1','rodos-official-9fntu2','rodos-official-9fntu3','rodos-official-9fnttw') group by product_slug order by product_slug;